DROP ALL OBJECTS;
CREATE SEQUENCE INBOX_MESSAGE_SEQ START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE ATTACHMENT_SEQ START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE CLASSIFICATION_SEQ START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE EXTRACTED_FACT_SEQ START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE REVIEW_ACTION_SEQ START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE AUDIT_EVENT_SEQ START WITH 1 INCREMENT BY 1;
CREATE TABLE INBOX_MESSAGE (ID BIGINT PRIMARY KEY, INTERNET_MESSAGE_ID VARCHAR(512) UNIQUE, SENDER_ADDRESS VARCHAR(512) NOT NULL, SUBJECT_LINE VARCHAR(1000), RECEIVED_AT TIMESTAMP WITH TIME ZONE NOT NULL, BODY_TEXT CLOB, STATUS VARCHAR(32) NOT NULL, AI_SUMMARY CLOB, PROCESSING_MS BIGINT, CREATED_AT TIMESTAMP WITH TIME ZONE NOT NULL, UPDATED_AT TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE ATTACHMENT (ID BIGINT PRIMARY KEY, MESSAGE_ID BIGINT NOT NULL REFERENCES INBOX_MESSAGE(ID), FILE_NAME VARCHAR(1000) NOT NULL, MIME_TYPE VARCHAR(255), SHA256 VARCHAR(64), PDF_TYPE VARCHAR(32), DETECTED_LANGUAGE VARCHAR(32), OCR_CONFIDENCE DECIMAL(5,4), PROCESSING_MS BIGINT, PROCESSING_STATUS VARCHAR(32) NOT NULL);
CREATE TABLE CLASSIFICATION (ID BIGINT PRIMARY KEY, MESSAGE_ID BIGINT NOT NULL REFERENCES INBOX_MESSAGE(ID), CATEGORY VARCHAR(32) NOT NULL, CONFIDENCE DECIMAL(5,4) NOT NULL, REASON VARCHAR(2000) NOT NULL, MODEL_NAME VARCHAR(255), CREATED_AT TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE EXTRACTED_FACT (ID BIGINT PRIMARY KEY, MESSAGE_ID BIGINT NOT NULL REFERENCES INBOX_MESSAGE(ID), ATTACHMENT_ID BIGINT REFERENCES ATTACHMENT(ID), FACT_GROUP VARCHAR(64) NOT NULL, FIELD_NAME VARCHAR(128) NOT NULL, FIELD_VALUE CLOB, CONFIDENCE DECIMAL(5,4) NOT NULL, SOURCE_TYPE VARCHAR(16) NOT NULL, SOURCE_NAME VARCHAR(1000) NOT NULL, SOURCE_PAGE INT, EVIDENCE_TEXT VARCHAR(4000), CREATED_AT TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE REVIEW_ACTION (ID BIGINT PRIMARY KEY, MESSAGE_ID BIGINT NOT NULL REFERENCES INBOX_MESSAGE(ID), REVIEWER VARCHAR(255) NOT NULL, ACTION_TYPE VARCHAR(32) NOT NULL, FIELD_NAME VARCHAR(128), PREVIOUS_VALUE CLOB, NEW_VALUE CLOB, NOTE VARCHAR(2000), CREATED_AT TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE AUDIT_EVENT (ID BIGINT PRIMARY KEY, MESSAGE_ID BIGINT REFERENCES INBOX_MESSAGE(ID), EVENT_TYPE VARCHAR(64) NOT NULL, ACTOR_TYPE VARCHAR(32) NOT NULL, ACTOR_ID VARCHAR(255), DETAILS_JSON CLOB, CREATED_AT TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL);
